import React, { useState } from 'react'
import { useLocation, useParams } from 'react-router-dom';
import { Divider } from "@heroui/react";
import EntityDetailsTabs from './EntityDetailsTabs';

function EntityDetails() {
    const location = useLocation()
    console.log("location", location);




    const [item, setitem] = useState(location.state.item ? location.state.item : null)
    // console.log('category_id', category)
    return (
        <div className="w-full-md mt-10 sm:mt-0">
            <div className="space-y-1">
                <h4 className="text-medium font-medium ">{item ? item.title : ""}</h4>
                <p className="text-small text-default-400">{item && item.description ? item.description : "No description availabe"}</p>
            </div>
            <Divider className="my-4" />
            <EntityDetailsTabs entity={item} />
            <div className="flex h-5 items-center space-x-4 text-small">
                {/* <div>Blog</div>
                <Divider orientation="vertical" />
                <div>Docs</div>
                <Divider orientation="vertical" />
                <div>Source</div> */}
            </div>
        </div>
    );
}

export default EntityDetails
